import React from 'react';

const AYUR_GREEN = '#6B8E23';
const AYUR_LIGHT_BG = '#F5F9F0';

const About = () => {
  const [isMobile, setIsMobile] = React.useState(window.innerWidth < 768);

  React.useEffect(() => {
    const handleResize = () => {
      setIsMobile(window.innerWidth < 768);
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return (
    <section id="about" style={{
      position: 'relative',
      padding: isMobile ? '3rem 1rem' : '5rem 2rem',
      background: 'linear-gradient(135deg, #F5F9F0 0%, #FAFFF6 50%, #F0F9EA 100%)',
      overflow: 'hidden',
      fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif"
    }}>
      <div style={{
        maxWidth: '1400px',
        margin: '0 auto',
        position: 'relative'
      }}>
        {/* Heading */}
        <h2 style={{
          fontSize: isMobile ? '2rem' : '3rem',
          fontWeight: 900,
          color: AYUR_GREEN,
          marginBottom: isMobile ? '2.5rem' : '4rem',
          textAlign: 'center',
          letterSpacing: '-0.02em'
        }}>
          About Our Retreat
        </h2>

        {/* Main Content Grid */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: isMobile ? '1fr' : '300px 1fr 300px',
          gap: isMobile ? '2rem' : '3rem',
          alignItems: 'center',
          position: 'relative'
        }}>
          {/* Left Image - Bottom Aligned */}
          {!isMobile && (
            <div className="left-image" style={{
              position: 'sticky',
              top: '2rem',
              height: 'fit-content'
            }}>
              <div style={{
                width: '100%',
                height: '360px',
                borderRadius: '24px',
                overflow: 'hidden',
                boxShadow: '0 12px 40px rgba(0, 0, 0, 0.12)',
                backgroundColor: '#e8f0dc'
              }}>
                <img 
                  src="about4.webp" 
                  alt="Group yoga class"
                  style={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover',
                    objectPosition: 'center'
                  }}
                />
              </div>
            </div>
          )}

          {/* Center Content */}
          <div style={{
            textAlign: 'center',
            padding: isMobile ? '0' : '2rem',
            zIndex: 2
          }}>
            {/* Intro Text */}
            <p style={{
              fontSize: isMobile ? '1rem' : '1.2rem',
              lineHeight: '1.7',
              color: '#6B7280',
              marginBottom: '1.5rem',
              fontWeight: 500
            }}>
              At <span style={{ fontWeight: 800, color: AYUR_GREEN }}>Himalayan Ayurveda Retreat</span>, we offer authentic Ayurvedic healing experiences in the spiritual heart of Rishikesh.
            </p>

            {/* Service Pills */}
            <div style={{
              display: 'flex',
              justifyContent: 'center',
              gap: isMobile ? '0.6rem' : '0.8rem',
              flexWrap: 'wrap',
              marginBottom: '2rem'
            }}>
              {['Yoga & Meditation', 'Panchakarma', 'Ayurvedic Therapy'].map((service, i) => (
                <span key={i} style={{
                  display: 'inline-block',
                  padding: isMobile ? '0.5rem 0.9rem' : '0.6rem 1.2rem',
                  backgroundColor: '#E8F0DC',
                  borderRadius: '24px',
                  color: AYUR_GREEN,
                  fontWeight: 700,
                  fontSize: isMobile ? '0.85rem' : '0.95rem',
                  letterSpacing: '0.3px',
                  border: `1px solid ${AYUR_GREEN}20`,
                  transition: 'all 0.3s ease',
                  cursor: 'pointer'
                }}
                onMouseEnter={(e) => {
                  e.target.style.backgroundColor = AYUR_GREEN;
                  e.target.style.color = 'white';
                  e.target.style.transform = 'translateY(-2px)';
                }}
                onMouseLeave={(e) => {
                  e.target.style.backgroundColor = '#E8F0DC';
                  e.target.style.color = AYUR_GREEN;
                  e.target.style.transform = 'translateY(0)';
                }}>
                  {service}
                </span>
              ))}
            </div>

            {/* Description Text */}
            <p style={{
              fontSize: isMobile ? '0.95rem' : '1.1rem',
              lineHeight: '1.75',
              color: '#6B7280',
              fontWeight: 400,
              letterSpacing: '0.3px'
            }}>
              Our retreat combines traditional Ayurvedic treatments with comfortable accommodation, providing a sanctuary for healing and transformation amidst the tranquil beauty of the Himalayas.
            </p>
          </div>

          {/* Right Image - Top Aligned */}
          {!isMobile && (
            <div className="right-image" style={{
              position: 'sticky',
              top: '2rem',
              height: 'fit-content'
            }}>
              <div style={{
                width: '100%',
                height: '360px',
                borderRadius: '24px',
                overflow: 'hidden',
                boxShadow: '0 12px 40px rgba(0, 0, 0, 0.12)',
                backgroundColor: '#e8f0dc'
              }}>
                <img 
                  src="about2.webp" 
                  alt="Woman in yoga stretch"
                  style={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover',
                    objectPosition: 'center'
                  }}
                />
              </div>
            </div>
          )}

          {/* Mobile Images */}
          {isMobile && (
            <>
              <div style={{
                width: '100%',
                height: '240px',
                borderRadius: '20px',
                overflow: 'hidden',
                boxShadow: '0 8px 24px rgba(0, 0, 0, 0.1)',
                backgroundColor: '#e8f0dc'
              }}>
                <img 
                  src="about4.webp" 
                  alt="Group yoga class"
                  style={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover',
                    objectPosition: 'center'
                  }}
                />
              </div>
              <div style={{
                width: '100%',
                height: '240px',
                borderRadius: '20px',
                overflow: 'hidden',
                boxShadow: '0 8px 24px rgba(0, 0, 0, 0.1)',
                backgroundColor: '#e8f0dc'
              }}>
                <img 
                  src="about2.webp" 
                  alt="Woman in yoga stretch"
                  style={{
                    width: '100%',
                    height: '100%',
                    objectFit: 'cover',
                    objectPosition: 'center'
                  }}
                />
              </div>
            </>
          )}
        </div>
      </div>

      <style>{`
        @media (max-width: 968px) {
          #about > div > div:nth-child(2) {
            min-height: 360px !important;
          }
          .top-right-image,
          .bottom-left-image {
            width: 280px !important;
            height: 140px !important;
          }
          .top-right-image {
            right: -120px !important;
          }
          .bottom-left-image {
            left: -120px !important;
          }
          #about > div > div:nth-child(2) > div:nth-child(2) {
            padding: 2rem 1.5rem !important;
          }
        }

        @media (max-width: 640px) {
          #about {
            padding: 2rem 1rem !important;
          }
          #about h2 {
            font-size: 1.75rem !important;
            margin-bottom: 1.25rem !important;
          }
          #about > div > div:nth-child(2) {
            min-height: 460px !important;
          }
          .top-right-image,
          .bottom-left-image {
            width: 220px !important;
            height: 120px !important;
            border-radius: 50px 0 0 50px !important;
          }
          .top-right-image {
            right: -90px !important;
          }
          .bottom-left-image {
            left: -90px !important;
            border-radius: 0 50px 50px 0 !important;
          }
          #about > div > div:nth-child(2) > div:nth-child(2) {
            padding: 1.5rem 1rem !important;
          }
          #about > div > div:nth-child(2) > div:nth-child(2) p {
            font-size: 0.95rem !important;
          }
        }

        @media (max-width: 480px) {
          .top-right-image,
          .bottom-left-image {
            width: 180px !important;
            height: 100px !important;
            border-radius: 40px 0 0 40px !important;
          }
          .top-right-image {
            right: -40px !important;
          }
          .bottom-left-image {
            left: -40px !important;
            border-radius: 0 40px 40px 0 !important;
          }
        }
      `}</style>
    </section>
  );
};

export default About;
